    if(!dx11){Need(D3D12CreateDevice(adapter.Get(),D3D_FEATURE_LEVEL_11_0,IID_PPV_ARGS(&device)),"Private DX12 unavailable");D3D12_COMMAND_QUEUE_DESC desc{};desc.Type=D3D12_COMMAND_LIST_TYPE_DIRECT;Need(device->CreateCommandQueue(&desc,IID_PPV_ARGS(&queue)),"Private queue unavailable");Need(device->CreateCommandAllocator(D3D12_COMMAND_LIST_TYPE_DIRECT,IID_PPV_ARGS(&allocator)),"Private allocator unavailable");Need(device->CreateCommandList(0,D3D12_COMMAND_LIST_TYPE_DIRECT,allocator.Get(),nullptr,IID_PPV_ARGS(&commands)),"Private commands unavailable");Need(commands->Close(),"Private commands close failed");}
